    // -- state registers: THESE ARE THE RESONATORS --
    reg signed [WIDTH-1:0]        x          [0:N-1];
    reg signed [WIDTH-1:0]        v          [0:N-1];
    reg signed [ENERGY_WIDTH-1:0] energy_ema [0:N-1];

    integer i;

    always @(posedge clk) begin
        if (rst) begin
            for (i = 0; i < N; i = i + 1) begin
                x[i]          <= 0;
                v[i]          <= 0;
                energy_ema[i] <= 0;
                detected[i]   <= 1'b0;
            end
        end else begin
            for (i = 0; i < N; i = i + 1) begin: step
                reg signed [2*WIDTH-1:0] k1x_full, k2v_full, k3drive_full;
                reg signed [2*WIDTH-1:0] cleft_full, cright_full;
                reg signed [WIDTH-1:0]   k1x, k2v, k3drive, cleft, cright, v_new, x_new, gated_x;
                reg signed [ENERGY_WIDTH-1:0] x2_full, energy_new;
                reg gate_active, was_above, now_above;

                k1x_full = $signed(k1_of(i)) * $signed(x[i]);
                k2v_full = $signed(k2_of(i)) * $signed(v[i]);
                k3drive_full = $signed(k3_of(i)) * $signed(drive);
                k1x     = k1x_full     >>> FRAC_BITS;
                k2v     = k2v_full     >>> FRAC_BITS;
                k3drive = k3drive_full >>> FRAC_BITS;

                // nearest-neighbor coupling: bond (i-1) to the left, bond i to the right
                cleft_full  = (i > 0)     ? ($signed(bond_of(i-1)) * $signed(x[i-1])) : 0;
                cright_full = (i < N - 1) ? ($signed(bond_of(i))   * $signed(x[i+1])) : 0;
                cleft  = cleft_full  >>> FRAC_BITS;
                cright = cright_full >>> FRAC_BITS;

                v_new = v[i] - k1x - k2v + k3drive + cleft + cright;
                x_new = x[i] + (v_new >>> DT_SHIFT);

                gate_active = (x_new >= GATE_THRESH) || (x_new <= -GATE_THRESH);
                gated_x = gate_active ? x_new : {WIDTH{1'b0}};

                x2_full = $signed(gated_x) * $signed(gated_x);
                was_above = energy_ema[i] >= thresh2_of(i);
                if (gate_active)
                    energy_new = energy_ema[i] + ((x2_full - energy_ema[i]) >>> ALPHA_SHIFT);
                else
                    energy_new = energy_ema[i] - (energy_ema[i] >>> ALPHA_SHIFT);
                now_above = energy_new >= thresh2_of(i);

                x[i]          <= x_new;
                v[i]          <= v_new;
                energy_ema[i] <= energy_new;
                detected[i]   <= now_above && !was_above;
            end
        end
    end

endmodule
